+function NextValue(p: PUtf8Char; var v: PtrUInt): PUtf8Char;
+var
+  c: PtrUInt;
+begin
+  result := nil;
+  c := PtrUInt(p^) - ord('0');
+  if c > 9 then
+    exit;
+  v := c;
+  repeat
+    inc(p);
+    c := PtrUInt(p^) - ord('0');
+    if c > 9 then
+      break;
+    v := v * 10 + c;
+  until false;
+  result := p;
+end;
