+  p := GotoNextNotSpace(p);
+  if p^ = '-' then
+  begin
+    neg := -neg;
+    inc(p);
+  end;
+  p := NextValue(p, v);
+  if p = nil then
+    exit;
+  case p^ of
+    #0:
+      begin
+        if v <= MAX_TIMESPAN then // '123'
+        begin
+          days := v;
+          result := p; // success
+        end;
+        exit;
+      end;
+    ':':
+      Hour := v;
+    '.':
+      begin
+        if v > MAX_TIMESPAN then
+          exit;
+        days := v;
+        p := NextValue(p + 1, v);
+        if (p = nil) or
+           (p^ <> ':') then
+          exit;
+        Hour := v;
+      end;
+  else
+    exit;
+  end;
+  if v > 23 then
+    exit;
+  p := NextValue(p + 1, v);
+  if (p = nil) or
